using System;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Linq;using System.Text.RegularExpressions;
class UpdateRelease {
 public Version Version;public string Tag,Installer,Checksums;
 public static UpdateRelease Parse(string json){var release=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);object raw;string tag=release!=null&&release.TryGetValue("tag_name",out raw)?raw as string:null;Version version;if(String.IsNullOrWhiteSpace(tag)||!System.Version.TryParse(tag.TrimStart('v'),out version))throw new Exception("Release version is invalid.");var result=new UpdateRelease{Version=version,Tag=tag};if(!release.TryGetValue("assets",out raw)||raw is string||!(raw is IEnumerable))throw new Exception("The release has no asset list.");
  foreach(object item in (IEnumerable)raw){var asset=item as IDictionary<string,object>;if(asset==null)continue;object nameValue,urlValue;if(!asset.TryGetValue("name",out nameValue)||!asset.TryGetValue("browser_download_url",out urlValue))continue;string name=nameValue as string,url=urlValue as string;if(name!="MultiVPNConnect-Setup.exe"&&name!="SHA256SUMS.txt")continue;string expected="https://github.com/CS-Colin/MultiVPNConnect/releases/download/"+Uri.EscapeDataString(tag)+"/"+name;if(url!=expected)throw new Exception("Unexpected update download source.");if(name=="MultiVPNConnect-Setup.exe"){if(result.Installer!=null)throw new Exception("Duplicate installer assets in release.");result.Installer=url;}else{if(result.Checksums!=null)throw new Exception("Duplicate checksum assets in release.");result.Checksums=url;}}
  if(result.Installer==null||result.Checksums==null)throw new Exception("This release has no compatible installer and checksum.");return result;
 }
 public static string InstallerHash(string sums){var matches=sums.Split('\n').Select(l=>Regex.Match(l.Trim(),@"^([a-fA-F0-9]{64})\s+\*?MultiVPNConnect-Setup\.exe$")).Where(m=>m.Success).ToArray();if(matches.Length!=1)throw new Exception("The release checksum file is invalid.");return matches[0].Groups[1].Value;}
}
